bool generate_iv(int size, int source, std::string& iv) {
    if (size <= 0) {
        std::cerr << "Invalid size for IV." << std::endl;
        return false;
    }

    iv.resize(size);
    unsigned char* buffer = reinterpret_cast<unsigned char*>(const_cast<char*>(iv.data()));

    if (source == 0) {
        FILE* fp = fopen("/dev/random", "r");
        if (!fp) {
            std::cerr << "/dev/random cannot be opened." << std::endl;
            return false;
        }

        if (fread(buffer, 1, size, fp) != static_cast<size_t>(size)) {
            fclose(fp);
            std::cerr << "Failed to read from /dev/random." << std::endl;
            return false;
        }

        fclose(fp);
    }
    else if (source == 1) {
        FILE* fp = fopen("/dev/urandom", "r");
        if (!fp) {
            std::cerr << "/dev/urandom cannot be opened." << std::endl;
            return false;
        }

        if (fread(buffer, 1, size, fp) != static_cast<size_t>(size)) {
            fclose(fp);
            std::cerr << "Failed to read from /dev/urandom." << std::endl;
            return false;
        }

        fclose(fp);
    }
    else {
        for (int i = 0; i < size; ++i) {
            buffer[i] = static_cast<unsigned char>(f_rand());
        }
    }

    return true;
}

