// Constants for source
const int RANDOM = 1;
const int URANDOM = 2;

std::string generate_iv(int size, int source = 0) {
    if (size <= 0) {
        throw std::invalid_argument("Invalid IV size");
    }

    std::string iv(size, 0);

    if (source == RANDOM || source == URANDOM) {
        std::string dev_path = (source == RANDOM) ? "/dev/random" : "/dev/urandom";
        std::ifstream dev_file(dev_path.c_str(), std::ios::binary | std::ios::in);

        if (!dev_file) {
            throw std::runtime_error("Failed to open randomness source");
        }

        dev_file.read(&iv[0], size);
        if (!dev_file) {
            throw std::runtime_error("Failed to read from randomness source");
        }
    } else if (source == 0) {
        f_rand(&iv[0], size);
    } else {
        throw std::invalid_argument("Invalid randomness source specified");
    }

    return iv;
}

