std::string generate_iv(int size, int source = 0) {
    if (size <= 0) {
        std::string error = "Invalid size specified.";
        std::cerr << error << std::endl;
        return "false";
    }

    unsigned char *iv = new unsigned char[size];
    if (!iv) {
        std::string error = "Memory allocation failed.";
        std::cerr << error << std::endl;
        return "false";
    }

    int fd;
    if (source == 0) {
        fd = open("/dev/random", O_RDONLY);
    } else if (source == 1) {
        fd = open("/dev/urandom", O_RDONLY);
    } else {
        fd = -1;
    }

    if (fd != -1) {
        ssize_t read_bytes = read(fd, iv, size);
        close(fd);
        if (read_bytes != static_cast<ssize_t>(size)) {
            std::string error = "Failed to read sufficient bytes from randomness source.";
            std::cerr << error << std::endl;
            delete[] iv;
            return "false";
        }
    } else {
        // Use a user-defined random function f_rand to generate the IV
        for (int i = 0; i < size; ++i) {
            iv[i] = static_cast<unsigned char>(f_rand());
        }
    }

    std::string result(reinterpret_cast<char*>(iv), size);
    delete[] iv;
    return result;
}
